// ============================================================
// PHASE 1: Extract brand names & descriptions from KeHE email
// Parses HTML body for brand blocks (orange #f07327 headers)
// Handles both Gmail Trigger and IMAP node output formats
// ============================================================

const item = $input.first().json;

// Gmail Trigger: html is in item.html or item.textHtml
// IMAP node: html is in item.html or item.textHtml
const html = item.html || item.textHtml || '';
const text = item.text || item.textPlain || item.snippet || '';

// Gmail Trigger puts subject in item.subject or item.headers?.subject
const subject = item.subject || (item.headers && item.headers.subject) || '';
const receivedDate = item.date || item.internalDate || new Date().toISOString();

// Extract brand names from bold orange text in HTML
const brandRegex = /<b>([^<]{2,60})<\/b><\/span><\/p>[\s\S]*?<span style="font-size:16px">([^<]{20,500})<\/span>/gi;
const brands = [];
const seen = new Set();
let match;

while ((match = brandRegex.exec(html)) !== null) {
  const name = match[1].trim();
  const desc = match[2].trim()
    .replace(/\u2011/g, '-')
    .replace(/\u2019/g, "'")
    .replace(/\u2018/g, "'")
    .replace(/\s+/g, ' ');

  if (!seen.has(name.toLowerCase()) && name.length > 2 && name.length < 60) {
    seen.add(name.toLowerCase());

    // Guess category from description
    let category = 'Consumer Goods';
    const descLower = desc.toLowerCase();
    if (descLower.includes('coffee') || descLower.includes('tea') || descLower.includes('beverage') || descLower.includes('drink') || descLower.includes('water') || descLower.includes('soda')) category = 'Food & Beverage';
    else if (descLower.includes('food') || descLower.includes('snack') || descLower.includes('cookie') || descLower.includes('noodle') || descLower.includes('olive') || descLower.includes('butter') || descLower.includes('chocolate') || descLower.includes('protein')) category = 'Food & Beverage';
    else if (descLower.includes('pet') || descLower.includes('dog') || descLower.includes('cat')) category = 'Pet Products';
    else if (descLower.includes('beauty') || descLower.includes('skin') || descLower.includes('hair') || descLower.includes('grooming') || descLower.includes('oral') || descLower.includes('toothpaste')) category = 'Health & Beauty';
    else if (descLower.includes('supplement') || descLower.includes('vitamin') || descLower.includes('mushroom') || descLower.includes('wellness') || descLower.includes('nutrition') || descLower.includes('fitness')) category = 'Health & Wellness';
    else if (descLower.includes('household') || descLower.includes('cleaning') || descLower.includes('personal care')) category = 'Household & Personal Care';

    brands.push({
      brand_name: name,
      brand_description: desc,
      brand_category: category,
      kehe_email_subject: subject,
      kehe_feature_date: receivedDate,
      source: 'KeHE Spotlight Email'
    });
  }
}

// Fallback: parse from plain text if HTML parsing found nothing
if (brands.length === 0 && text) {
  const knownBrands = text.match(/^([A-Z][A-Za-z\s&'.\-]+?)(?:\s+is\s|\s+are\s|\s+delivers|\s+creates|\s+crafts|\s+specializes|\s+transforms)/gm);
  if (knownBrands) {
    for (const line of knownBrands) {
      const name = line.replace(/\s+(is|are|delivers|creates|crafts|specializes|transforms).*/, '').trim();
      if (name.length > 2 && name.length < 60 && !seen.has(name.toLowerCase())) {
        seen.add(name.toLowerCase());
        brands.push({
          brand_name: name,
          brand_description: '',
          brand_category: 'Consumer Goods',
          kehe_email_subject: subject,
          kehe_feature_date: receivedDate,
          source: 'KeHE Spotlight Email'
        });
      }
    }
  }
}

return brands.map(b => ({ json: b }));

