// ============================================================
// PHASE 3: Limit to top 2-3 contacts per brand
// Prioritizes marketing & partnerships titles
// ============================================================

const brandData = $('Process Each Brand').item.json;
const apolloData = $('Apollo.io - Enrich Company').item.json;
const linkedInResults = $input.first().json;

// Parse results from PhantomBuster / LinkedIn
let contacts = [];
if (linkedInResults.resultObject) {
  try {
    contacts = JSON.parse(linkedInResults.resultObject) || [];
  } catch(e) { contacts = []; }
} else if (Array.isArray(linkedInResults.data)) {
  contacts = linkedInResults.data;
} else if (Array.isArray(linkedInResults)) {
  contacts = linkedInResults;
}

// Title priority scoring
const titlePriority = {
  'influencer': 10, 'partnership': 9, 'creator': 8,
  'brand manager': 7, 'marketing director': 7, 'head of marketing': 7,
  'vp marketing': 6, 'vp of marketing': 6, 'vice president marketing': 6,
  'cmo': 5, 'chief marketing': 5,
  'digital marketing': 4, 'social media': 4,
  'marketing manager': 3, 'growth': 3,
  'marketing': 2, 'communications': 1
};

function scoreTitle(title) {
  if (!title) return 0;
  const lower = title.toLowerCase();
  let maxScore = 0;
  for (const [keyword, score] of Object.entries(titlePriority)) {
    if (lower.includes(keyword)) maxScore = Math.max(maxScore, score);
  }
  return maxScore;
}

const scored = contacts
  .filter(c => c.full_name || c.name || (c.firstName && c.lastName))
  .map(c => ({
    full_name: c.full_name || c.name || `${c.firstName || ''} ${c.lastName || ''}`.trim(),
    first_name: c.first_name || c.firstName || (c.full_name || c.name || '').split(' ')[0],
    last_name: c.last_name || c.lastName || (c.full_name || c.name || '').split(' ').slice(1).join(' '),
    title: c.title || c.headline || '',
    linkedin_url: c.linkedin_url || c.profileUrl || c.linkedInUrl || '',
    title_score: scoreTitle(c.title || c.headline || ''),
    brand_name: brandData.brand_name,
    brand_description: brandData.brand_description,
    brand_category: brandData.brand_category,
    kehe_feature_date: brandData.kehe_feature_date,
    company_website: apolloData.organization?.website_url || apolloData.organization?.primary_domain || '',
    employee_count: apolloData.organization?.estimated_num_employees || 0,
    company_industry: apolloData.organization?.industry || '',
    company_city: apolloData.organization?.city || '',
    company_state: apolloData.organization?.state || ''
  }))
  .sort((a, b) => b.title_score - a.title_score)
  .slice(0, 3);

return scored.length > 0 ? scored.map(c => ({ json: c })) : [{ json: { skip: true, reason: 'No contacts found', brand_name: brandData.brand_name } }];

// ============================================================
// PHASE 6: Generate 3 personalized outreach emails
// Template 1: Initial outreach (KeHE Spotlight hook)
// Template 2: Follow-up (case study angle)
// Template 3: Final follow-up (FOMO/scarcity)
//
// All 3 emails are passed to Smartlead as custom fields.
// Smartlead owns the sequence: sending, delays, warmup,
// reply detection, and unsubscribe handling.
// ============================================================

const contact = $('Limit to Top 2-3 Contacts').item.json;
const email = $('FindyMail - Find Email').item.json.email;
const brandName = contact.brand_name;
const brandDescription = contact.brand_description;
const firstName = contact.first_name;
const contactTitle = contact.title;
const category = contact.brand_category;
const website = contact.company_website;
const employeeCount = contact.employee_count;

// Determine the right role-based opener
let roleHook = '';
if (contactTitle.toLowerCase().includes('cmo') || contactTitle.toLowerCase().includes('chief')) {
  roleHook = 'Given your role steering the marketing vision';
} else if (contactTitle.toLowerCase().includes('influencer') || contactTitle.toLowerCase().includes('creator') || contactTitle.toLowerCase().includes('partnership')) {
  roleHook = 'Since you\'re leading the influencer/partnerships side';
} else if (contactTitle.toLowerCase().includes('brand manager')) {
  roleHook = 'As the person closest to the brand\'s growth';
} else {
  roleHook = 'With the marketing momentum you\'re building';
}

// Determine category-specific case study reference
let caseStudy = '';
if (category === 'Food & Beverage') {
  caseStudy = 'We recently helped an emerging kombucha brand generate 2.3M impressions and a 340% increase in retail velocity within 60 days through a targeted micro-influencer campaign across Instagram and TikTok.';
} else if (category === 'Health & Wellness' || category === 'Health & Beauty') {
  caseStudy = 'We recently helped a clean beauty brand drive 1.8M impressions and a 280% lift in DTC sales through a strategic influencer seeding campaign with wellness creators on Instagram and TikTok.';
} else if (category === 'Pet Products') {
  caseStudy = 'We recently helped a premium pet treat brand generate 1.5M impressions and a 220% increase in Amazon sales through pet influencer partnerships across Instagram, TikTok, and YouTube.';
} else {
  caseStudy = 'We recently helped an emerging CPG brand drive 2M+ impressions and a 300% increase in retail velocity within 90 days through strategic influencer partnerships.';
}

// ===== EMAIL 1: Initial Outreach =====
const subject1 = `Congrats on the KeHE Spotlight, ${brandName}!`;
const body1 = `Hi ${firstName},

I saw ${brandName} featured as a Spotlight Brand at the 2026 KeHE Summer Show — congrats on the momentum! ${brandDescription ? `"${brandDescription.substring(0, 120)}..." really stood out to me.` : 'Really cool to see the traction you\'re building.'}

${roleHook}, I wanted to reach out because we work specifically with emerging CPG brands in the ${category.toLowerCase()} space to amplify their retail growth through strategic influencer partnerships.

At ENT Agency, we\'ve found that brands hitting inflection points like a KeHE Spotlight feature see the biggest ROI from influencer marketing — you\'ve got the distribution momentum, and creator content is what drives the pull-through at shelf.

Would you be open to a quick 15-minute call to explore if there\'s a fit? Happy to share some specific ideas for ${brandName}.

Best,

{{sender_name}}
ENT Agency
{{sender_title}}`;

// ===== EMAIL 2: Follow-Up (Case Study) =====
const subject2 = `Quick case study for ${brandName}`;
const body2 = `Hi ${firstName},

Wanted to circle back with something concrete that might be relevant for ${brandName}.

${caseStudy}

The playbook we\'d tailor for ${brandName} would focus on:
• Identifying 15-30 creators who authentically align with your brand story
• Seeding product + building genuine relationships (not just one-off posts)
• Driving both awareness AND measurable retail velocity through strategic content

Given the KeHE Spotlight feature and your growth trajectory, the timing could be ideal to layer in influencer as a channel.

Worth a quick chat?

Best,

{{sender_name}}
ENT Agency`;

// ===== EMAIL 3: Follow-Up (FOMO/Scarcity) =====
const subject3 = `Last thought on ${brandName} + influencer marketing`;
const body3 = `Hi ${firstName},

Last note from me — I know your inbox is probably packed.

I\'ll keep it short: we\'re currently onboarding Q2 brand partners and have 2-3 spots left for ${category.toLowerCase()} brands. Given ${brandName}\'s KeHE feature and growth trajectory, it felt like a natural fit.

If the timing isn\'t right, no worries at all. But if influencer marketing is on your radar for the next quarter, I\'d love to have a quick conversation before our calendar fills up.

Here\'s my Calendly if it\'s easier to grab a slot directly: {{calendly_link}}

Cheers,

{{sender_name}}
ENT Agency`;

return [{
  json: {
    contact_email: email,
    contact_first_name: firstName,
    contact_last_name: contact.last_name,
    contact_full_name: contact.full_name,
    contact_title: contactTitle,
    contact_linkedin: contact.linkedin_url,
    brand_name: brandName,
    brand_description: brandDescription,
    brand_category: category,
    company_website: website,
    employee_count: employeeCount,
    email_1_subject: subject1,
    email_1_body: body1,
    email_2_subject: subject2,
    email_2_body: body2,
    email_3_subject: subject3,
    email_3_body: body3,
    kehe_feature_date: contact.kehe_feature_date
  }
}];
